"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import { Archive, BarChart3, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleAlert, Columns3, Download, Filter, HelpCircle, Import, Mail, MoreHorizontal, Pencil, Rows3, Search, Star, Trash2, Upload, UserPlus, UsersRound, X, XCircle } from "lucide-react";
import { toast } from "sonner";
import { addGuest, addHousehold, bulkDeleteGuests, bulkUpdateGuests, deleteGuest, importGuests, quickUpdateGuest, setGuestsArchived } from "@/app/(dashboard)/guests/actions";
import { moveGuest } from "@/app/(dashboard)/tables/actions";
import { createClient } from "@/lib/supabase/browser";

export type GuestWorkspaceRow = {
  id: string; household_id: string | null; first_name: string; last_name: string | null; preferred_name: string | null; title: string | null; relationship_group: string | null;
  guest_type: string; age_group: string; email: string | null; phone: string | null; rsvp_status: string; invitation_status: string; is_vip: boolean;
  plus_one_allowed: boolean; plus_one_name: string | null; meal_option_id: string | null; dietary_requirements: string | null; allergies: string | null;
  accessibility_requirements: string | null; requires_highchair: boolean; requires_accommodation: boolean; accommodation_notes: string | null; requires_transport: boolean;
  transport_notes: string | null; gift_received: boolean; thank_you_sent: boolean; private_notes: string | null; invited_at: string | null; responded_at: string | null;
  created_at: string; updated_at: string; households: { id: string; household_name: string; email: string | null; guests: { id: string; rsvp_status: string }[] } | null;
  meal_options: { name: string } | null; guest_table_assignments: { table_id: string; tables: { name: string } | null }[];
};

type HouseholdOption = { id: string; name: string; email: string | null; rsvpCode: string; guestCount: number; attending: number; awaiting: number };
type TableOption = { id: string; name: string; capacity: number; assigned: number };
type Option = { id: string; name: string };
type Column = "household" | "type" | "rsvp" | "meal" | "dietary" | "table" | "invitation" | "contact";
type Filters = { quick: string; advanced: string[]; householdId: string; tableId: string; archived: boolean };
type SavedView = { id: string; name: string; custom?: boolean; filters: Filters; sort: { field: string; direction: "asc" | "desc" }; columns: Record<Column, boolean>; density: "compact" | "comfortable" };
type GuestDetailPayload = { guest: Record<string, unknown> & { households?: Record<string, unknown> & { guests?: Array<{ id: string; first_name: string; last_name: string; rsvp_status: string }> }; meal_options?: { name: string } }; assignment: Record<string, unknown> | null; activity: Array<{ id: string; action: string; description: string | null; created_at: string }>; rsvpHistory: Array<{ id: string; attending: boolean | null; dietary_requirements: string | null; message_to_couple: string | null; submitted_at: string; reviewed: boolean }> };

const defaultColumns: Record<Column, boolean> = { household: true, type: true, rsvp: true, meal: true, dietary: true, table: true, invitation: true, contact: true };
const emptyFilters: Filters = { quick: "all", advanced: [], householdId: "", tableId: "", archived: false };
const quickFilters = [["all", "All guests"], ["attending", "Attending"], ["awaiting", "Awaiting RSVP"], ["declined", "Declined"], ["day", "Day"], ["evening", "Evening"], ["no_table", "No table"], ["dietary", "Dietary"]] as const;
const advancedOptions = [["adult", "Adult"], ["child", "Child"], ["baby", "Baby"], ["vip", "VIP"], ["plus_one", "Plus-one allowed"], ["plus_one_missing", "Plus-one missing"], ["missing_email", "Missing email"], ["missing_phone", "Missing phone"], ["accommodation", "Accommodation required"], ["transport", "Transport required"], ["accessibility", "Accessibility requirements"], ["highchair", "Highchair required"], ["meal_missing", "Meal selection missing"], ["invitation_not_sent", "Invitation not sent"], ["thank_you_not_sent", "Thank-you not sent"]] as const;

export function GuestManagement({ initialGuests, households, tables, meals, archivedIds: initialArchived, weddingId, userId, userEmail, initialAddGuest, initialGuestId, initialHouseholdId, initialView, error, message }: { initialGuests: GuestWorkspaceRow[]; households: HouseholdOption[]; tables: TableOption[]; meals: Option[]; archivedIds: string[]; weddingId: string; userId: string; userEmail: string; initialAddGuest: boolean; initialGuestId?: string; initialHouseholdId?: string; initialView?: string; error?: string; message?: string }) {
  const storageKey = `wedding-hq-guest-workspace:${weddingId}:${userId}`;
  const [rows, setRows] = useState(initialGuests); const [archivedIds, setArchivedIds] = useState(new Set(initialArchived));
  const [filters, setFilters] = useState<Filters>(() => ({ ...emptyFilters, archived: initialView === "archived" })); const [search, setSearch] = useState(""); const [debouncedSearch, setDebouncedSearch] = useState("");
  const [sort, setSort] = useState<{ field: string; direction: "asc" | "desc" }>({ field: "last_name", direction: "asc" }); const [columns, setColumns] = useState(defaultColumns); const [density, setDensity] = useState<"compact" | "comfortable">("comfortable");
  const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(50); const [selected, setSelected] = useState<string[]>([]); const [advancedOpen, setAdvancedOpen] = useState(false);
  const [addGuestOpen, setAddGuestOpen] = useState(initialAddGuest); const [householdOpen, setHouseholdOpen] = useState(false); const [importOpen, setImportOpen] = useState(false); const [reminderOpen, setReminderOpen] = useState(false); const [analyticsOpen, setAnalyticsOpen] = useState(false);
  const [selectedGuestId, setSelectedGuestId] = useState<string | null>(initialGuestId || null); const [detailTab, setDetailTab] = useState("overview"); const [detail, setDetail] = useState<GuestDetailPayload | null>(null); const [detailLoading, setDetailLoading] = useState(false);
  const [savingId, setSavingId] = useState<string | null>(null); const [recentlyUpdated, setRecentlyUpdated] = useState<Set<string>>(new Set()); const [saveError, setSaveError] = useState<{ id: string; field: string; value: string | null; message: string } | null>(null);
  const [editors, setEditors] = useState<Record<string, string>>({}); const [customViews, setCustomViews] = useState<SavedView[]>([]); const [activeView, setActiveView] = useState(initialView || "all"); const [isPending, startTransition] = useTransition();
  const searchRef = useRef<HTMLInputElement>(null); const collaborationChannel = useRef<ReturnType<ReturnType<typeof createClient>["channel"]> | null>(null);

  const defaultViews = useMemo<SavedView[]>(() => [
    view("all", "All guests", emptyFilters), view("awaiting", "Awaiting RSVP", { ...emptyFilters, quick: "awaiting" }), view("attending-day", "Attending day guests", { ...emptyFilters, quick: "attending", advanced: ["day"] }),
    view("evening", "Evening guests", { ...emptyFilters, quick: "evening" }), view("dietary", "Dietary requirements", { ...emptyFilters, quick: "dietary" }), view("no-table", "No table assigned", { ...emptyFilters, quick: "no_table" }),
    view("missing", "Missing information", { ...emptyFilters, advanced: ["missing_email", "meal_missing"] }), view("archived", "Archived guests", { ...emptyFilters, archived: true }),
  ], []);

  useEffect(() => { setRows(initialGuests); setArchivedIds(new Set(initialArchived)); }, [initialGuests, initialArchived]);
  useEffect(() => { const timer = window.setTimeout(() => { setDebouncedSearch(search.trim().toLowerCase()); setPage(1); }, 180); return () => window.clearTimeout(timer); }, [search]);
  useEffect(() => { function shortcut(event: KeyboardEvent) { if (event.key === "/" && !(event.target as HTMLElement).matches("input,textarea,select")) { event.preventDefault(); searchRef.current?.focus(); } } window.addEventListener("keydown", shortcut); return () => window.removeEventListener("keydown", shortcut); }, []);
  useEffect(() => { try { const saved = JSON.parse(localStorage.getItem(storageKey) || "null") as { columns?: Record<Column, boolean>; density?: "compact" | "comfortable"; sort?: typeof sort; views?: SavedView[] } | null; if (saved?.columns) setColumns({ ...defaultColumns, ...saved.columns }); if (saved?.density) setDensity(saved.density); if (saved?.sort) setSort(saved.sort); if (saved?.views) setCustomViews(saved.views); } catch { localStorage.removeItem(storageKey); } }, [storageKey]);
  useEffect(() => { localStorage.setItem(storageKey, JSON.stringify({ columns, density, sort, views: customViews })); }, [columns, density, sort, customViews, storageKey]);

  useEffect(() => {
    const supabase = createClient();
    const channel = supabase.channel(`wedding:${weddingId}:guest-workspace`, { config: { presence: { key: userId } } })
      .on("postgres_changes", { event: "*", schema: "public", table: "guests", filter: `wedding_id=eq.${weddingId}` }, (payload) => {
        const changed = (payload.new || payload.old) as Partial<GuestWorkspaceRow>;
        if (!changed.id) return;
        if (payload.eventType === "DELETE") setRows((current) => current.filter((guest) => guest.id !== changed.id));
        else setRows((current) => current.map((guest) => guest.id === changed.id ? { ...guest, ...changed } : guest));
        setRecentlyUpdated((current) => new Set(current).add(changed.id!)); window.setTimeout(() => setRecentlyUpdated((current) => { const next = new Set(current); next.delete(changed.id!); return next; }), 3000);
      })
      .on("postgres_changes", { event: "*", schema: "public", table: "guest_table_assignments", filter: `wedding_id=eq.${weddingId}` }, (payload) => {
        const changed = (payload.new || payload.old) as { guest_id?: string; table_id?: string };
        if (!changed.guest_id) return; const table = tables.find((item) => item.id === changed.table_id);
        setRows((current) => current.map((guest) => guest.id === changed.guest_id ? { ...guest, guest_table_assignments: table ? [{ table_id: table.id, tables: { name: table.name } }] : [] } : guest));
      })
      .on("presence", { event: "sync" }, () => { const state = channel.presenceState<{ userId: string; email: string; editingGuestId?: string }>(); const next: Record<string, string> = {}; Object.values(state).flat().forEach((person) => { if (person.userId !== userId && person.editingGuestId) next[person.editingGuestId] = person.email.split("@")[0] || "A collaborator"; }); setEditors(next); })
      .subscribe((status) => { if (status === "SUBSCRIBED") void channel.track({ userId, email: userEmail }); });
    collaborationChannel.current = channel;
    return () => { collaborationChannel.current = null; void supabase.removeChannel(channel); };
  }, [weddingId, userId, userEmail, tables]);

  useEffect(() => { if (collaborationChannel.current) void collaborationChannel.current.track({ userId, email: userEmail, editingGuestId: selectedGuestId || undefined }); }, [selectedGuestId, userId, userEmail]);
  useEffect(() => { if (!selectedGuestId) { setDetail(null); return; } let active = true; setDetailLoading(true); fetch(`/api/guests/${selectedGuestId}`).then((response) => response.json()).then((payload) => { if (active) setDetail(payload); }).catch(() => { if (active) toast.error("Guest details could not be loaded."); }).finally(() => { if (active) setDetailLoading(false); }); return () => { active = false; }; }, [selectedGuestId]);

  const stats = useMemo(() => ({ total: rows.length, attending: rows.filter((guest) => guest.rsvp_status === "attending").length, awaiting: rows.filter(isAwaiting).length, declined: rows.filter((guest) => guest.rsvp_status === "declined").length, day: rows.filter((guest) => guest.guest_type === "day").length, evening: rows.filter((guest) => guest.guest_type === "evening").length, noTable: rows.filter((guest) => guest.rsvp_status === "attending" && !guest.guest_table_assignments?.length).length, dietary: rows.filter((guest) => Boolean(guest.dietary_requirements?.trim() || guest.allergies?.trim())).length }), [rows]);
  const duplicateIds = useMemo(() => { const seen = new Map<string, string>(); const duplicates = new Set<string>(); rows.forEach((guest) => { const key = guest.email?.trim().toLowerCase() || `${guest.first_name}|${guest.last_name || ""}`.toLowerCase(); if (seen.has(key)) { duplicates.add(guest.id); duplicates.add(seen.get(key)!); } else seen.set(key, guest.id); }); return duplicates; }, [rows]);
  const filtered = useMemo(() => rows.filter((guest) => {
    if (archivedIds.has(guest.id) !== filters.archived) return false;
    const tableName = guest.guest_table_assignments?.[0]?.tables?.name || ""; const searchable = [guest.first_name, guest.last_name, guest.preferred_name, guest.households?.household_name, guest.email, guest.phone, tableName, guest.dietary_requirements, guest.allergies, guest.private_notes].filter(Boolean).join(" ").toLowerCase();
    if (debouncedSearch && !searchable.includes(debouncedSearch)) return false;
    if (!matchQuick(guest, filters.quick)) return false;
    if (filters.householdId && guest.household_id !== filters.householdId) return false;
    if (filters.tableId && guest.guest_table_assignments?.[0]?.table_id !== filters.tableId) return false;
    return filters.advanced.every((filter) => matchAdvanced(guest, filter));
  }).sort((a, b) => compareGuests(a, b, sort.field, sort.direction)), [rows, archivedIds, filters, debouncedSearch, sort]);
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize)); const paged = filtered.slice((Math.min(page, totalPages) - 1) * pageSize, Math.min(page, totalPages) * pageSize); const allPageSelected = paged.length > 0 && paged.every((guest) => selected.includes(guest.id));
  const warningCounts = { noTable: stats.noTable, meal: rows.filter((guest) => guest.rsvp_status === "attending" && !guest.meal_option_id).length, contact: rows.filter((guest) => !guest.email && !guest.phone).length, plusOne: rows.filter((guest) => guest.plus_one_allowed && !guest.plus_one_name).length, transport: rows.filter((guest) => guest.requires_transport && !guest.transport_notes).length, accommodation: rows.filter((guest) => guest.requires_accommodation && !guest.accommodation_notes).length, duplicates: duplicateIds.size };
  const reminderGuests = filtered.filter((guest) => isAwaiting(guest) && guest.invitation_status === "sent" && Boolean(guest.email || guest.phone));

  function applyQuick(quick: string) { setFilters({ ...emptyFilters, quick }); setActiveView(quick); setPage(1); }
  function applyView(id: string) { const saved = [...defaultViews, ...customViews].find((item) => item.id === id); if (!saved) return; setActiveView(id); setFilters(saved.filters); setSort(saved.sort); setColumns(saved.columns); setDensity(saved.density); setPage(1); }
  function saveView() { const name = window.prompt("Name this guest view"); if (!name?.trim()) return; const saved: SavedView = { id: crypto.randomUUID(), name: name.trim(), custom: true, filters, sort, columns, density }; setCustomViews((current) => [...current, saved]); setActiveView(saved.id); toast.success("Guest view saved"); }
  function renameView() { const saved = customViews.find((item) => item.id === activeView); if (!saved) return; const name = window.prompt("Rename this view", saved.name); if (!name?.trim()) return; setCustomViews((current) => current.map((item) => item.id === activeView ? { ...item, name: name.trim() } : item)); }
  function deleteView() { if (!customViews.some((item) => item.id === activeView) || !confirm("Delete this saved view?")) return; setCustomViews((current) => current.filter((item) => item.id !== activeView)); applyView("all"); }

  function updateCell(guest: GuestWorkspaceRow, field: string, value: string | null) {
    const previous = rows; setSaveError(null); setSavingId(guest.id);
    if (field === "table_id") { const table = tables.find((item) => item.id === value); setRows((current) => current.map((item) => item.id === guest.id ? { ...item, guest_table_assignments: table ? [{ table_id: table.id, tables: { name: table.name } }] : [] } : item)); startTransition(async () => { try { await moveGuest(guest.id, value); toast.success("Table updated"); } catch (failure) { setRows(previous); setSaveError({ id: guest.id, field, value, message: failure instanceof Error ? failure.message : "Save failed" }); } finally { setSavingId(null); } }); return; }
    setRows((current) => current.map((item) => item.id === guest.id ? { ...item, [field]: value || null, ...(field === "meal_option_id" ? { meal_options: meals.find((meal) => meal.id === value) ? { name: meals.find((meal) => meal.id === value)!.name } : null } : {}) } : item));
    startTransition(async () => { try { await quickUpdateGuest(guest.id, field, value); toast.success("Guest updated"); } catch (failure) { setRows(previous); setSaveError({ id: guest.id, field, value, message: failure instanceof Error ? failure.message : "Save failed" }); } finally { setSavingId(null); } });
  }

  function performBulk(action: string, value?: string, explicitIds?: string[]) {
    const ids = explicitIds?.length ? explicitIds : selected;
    if (!ids.length) return;
    if ((action === "remove_table" || action === "archive" || action === "delete") && !confirm(action === "delete" ? `Permanently delete ${ids.length} guests? Household records will be kept.` : action === "archive" ? `Archive ${ids.length} guests?` : `Remove ${ids.length} guests from their tables?`)) return;
    const previous = rows; startTransition(async () => { try {
      if (action === "archive") { await setGuestsArchived(ids, true); setArchivedIds((current) => { const next = new Set(current); ids.forEach((id) => next.add(id)); return next; }); }
      else if (action === "delete") { await bulkDeleteGuests(ids); setRows((current) => current.filter((guest) => !ids.includes(guest.id))); }
      else if (action === "table") { for (const id of ids) await moveGuest(id, value || null); const table = tables.find((item) => item.id === value); setRows((current) => current.map((guest) => ids.includes(guest.id) ? { ...guest, guest_table_assignments: table ? [{ table_id: table.id, tables: { name: table.name } }] : [] } : guest)); }
      else { await bulkUpdateGuests(ids, action, value); setRows((current) => current.map((guest) => ids.includes(guest.id) ? optimisticBulk(guest, action, value, households) : guest)); }
      setSelected([]); toast.success(action === "reminder" ? "Reminder activity recorded — no message was sent" : "Guests updated");
    } catch (failure) { setRows(previous); toast.error(failure instanceof Error ? failure.message : "Bulk update failed"); } });
  }

  function removeOne(guest: GuestWorkspaceRow) { if (!confirm(`Permanently delete ${guest.first_name} ${guest.last_name || ""}? The household will be kept.`)) return; const previous = rows; setRows((current) => current.filter((item) => item.id !== guest.id)); startTransition(async () => { try { await deleteGuest(guest.id); toast.success("Guest deleted"); } catch (failure) { setRows(previous); toast.error(failure instanceof Error ? failure.message : "Delete failed"); } }); }
  function exportRows(items: GuestWorkspaceRow[], filename = "selected-guests.csv") { const headers = ["First name", "Last name", "Household", "Guest type", "RSVP", "Email", "Phone", "Meal", "Dietary", "Table"]; const lines = [headers, ...items.map((guest) => [guest.first_name, guest.last_name || "", guest.households?.household_name || "", guest.guest_type, guest.rsvp_status, guest.email || "", guest.phone || "", guest.meal_options?.name || "", guest.dietary_requirements || "", guest.guest_table_assignments?.[0]?.tables?.name || ""])].map((line) => line.map(csvCell).join(",")).join("\r\n"); const url = URL.createObjectURL(new Blob([lines], { type: "text/csv" })); const link = document.createElement("a"); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); }

  return <>
    <header className="guest-workspace-header"><div><div><h1>Guests</h1><span>{stats.total} total</span></div><dl><div><dt>Confirmed</dt><dd>{stats.attending}</dd></div><div><dt>Awaiting</dt><dd>{stats.awaiting}</dd></div><div><dt>Declined</dt><dd>{stats.declined}</dd></div></dl></div><div className="guest-header-actions"><button className="button button-primary" onClick={() => setAddGuestOpen(true)}><UserPlus />Add guest</button><button className="button button-secondary" onClick={() => setHouseholdOpen(true)}><UsersRound />Add household</button><button className="button button-secondary" onClick={() => setImportOpen(true)}><Upload />Import CSV</button><details className="guest-more-menu"><summary className="button button-secondary" aria-label="More guest actions"><MoreHorizontal /></summary><nav><Link href="/api/guests/export"><Download />Export guests</Link><Link href="/api/guests/export?report=dietary"><Download />Export dietary report</Link><Link href="/api/guests/export?report=meals"><Download />Export meal report</Link><button onClick={() => setReminderOpen(true)}><Mail />RSVP reminders</button><Link href="/settings">Manage meal options</Link><button onClick={() => applyView("archived")}><Archive />View archived guests</button></nav></details></div></header>
    {error && <div className="guest-error-state alert alert-error"><span>{error}</span><button onClick={() => location.reload()}>Retry</button></div>}{message && <div className="alert guest-message">{message}</div>}

    <section className="guest-summary-strip" aria-label="Guest summary filters">{[["all", "Total invited", stats.total], ["attending", "Attending", stats.attending], ["awaiting", "Awaiting RSVP", stats.awaiting], ["declined", "Declined", stats.declined], ["day", "Day guests", stats.day], ["evening", "Evening guests", stats.evening], ["no_table", "Unassigned", stats.noTable], ["dietary", "Dietary", stats.dietary]].map(([key, label, value]) => <button className={filters.quick === key ? "active" : ""} onClick={() => applyQuick(String(key))} key={String(key)}><span>{label}</span><strong>{value}</strong></button>)}</section>

    <section className="guest-command-bar"><div className="guest-view-picker"><select value={activeView} onChange={(event) => applyView(event.target.value)} aria-label="Saved guest view">{defaultViews.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}{customViews.length > 0 && <optgroup label="My views">{customViews.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</optgroup>}</select><button onClick={saveView}>Save view</button>{customViews.some((item) => item.id === activeView) && <><button onClick={renameView}>Rename</button><button onClick={deleteView}>Delete</button></>}</div><label className="guest-search"><Search /><input ref={searchRef} value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search names, household, contact, table, notes…" aria-label="Search guests" />{search && <button onClick={() => setSearch("")} aria-label="Clear search"><X /></button>}<kbd>/</kbd></label><button className={`button button-secondary ${advancedOpen ? "active" : ""}`} onClick={() => setAdvancedOpen((value) => !value)}><Filter />Filters</button><details className="guest-column-menu"><summary className="button button-secondary"><Columns3 />Columns</summary><div>{(Object.keys(defaultColumns) as Column[]).map((column) => <label key={column}><input type="checkbox" checked={columns[column]} onChange={() => setColumns((current) => ({ ...current, [column]: !current[column] }))} />{column}</label>)}</div></details><button className="button button-secondary guest-density" onClick={() => setDensity((value) => value === "compact" ? "comfortable" : "compact")}><Rows3 />{density}</button></section>
    <nav className="guest-quick-filters" aria-label="Quick guest filters">{quickFilters.map(([key, label]) => <button className={filters.quick === key ? "active" : ""} onClick={() => applyQuick(key)} key={key}>{label}</button>)}</nav>
    {advancedOpen && <section className="guest-advanced-filters"><div>{advancedOptions.map(([key, label]) => <label key={key}><input type="checkbox" checked={filters.advanced.includes(key)} onChange={() => setFilters((current) => ({ ...current, advanced: current.advanced.includes(key) ? current.advanced.filter((item) => item !== key) : [...current.advanced, key] }))} />{label}</label>)}</div><select value={filters.householdId} onChange={(event) => setFilters((current) => ({ ...current, householdId: event.target.value }))}><option value="">All households</option>{households.map((household) => <option value={household.id} key={household.id}>{household.name}</option>)}</select><select value={filters.tableId} onChange={(event) => setFilters((current) => ({ ...current, tableId: event.target.value }))}><option value="">All tables</option>{tables.map((table) => <option value={table.id} key={table.id}>{table.name}</option>)}</select><button onClick={() => { setFilters(emptyFilters); setSearch(""); }}>Clear all</button></section>}
    {(filters.quick !== "all" || filters.advanced.length > 0 || filters.householdId || filters.tableId || filters.archived) && <div className="guest-filter-chips"><span>{filtered.length} results</span>{filters.quick !== "all" && <button onClick={() => setFilters((current) => ({ ...current, quick: "all" }))}>{quickFilters.find(([key]) => key === filters.quick)?.[1]}<X /></button>}{filters.advanced.map((filter) => <button onClick={() => setFilters((current) => ({ ...current, advanced: current.advanced.filter((item) => item !== filter) }))} key={filter}>{advancedOptions.find(([key]) => key === filter)?.[1]}<X /></button>)}{filters.archived && <button onClick={() => setFilters((current) => ({ ...current, archived: false }))}>Archived<X /></button>}<button className="clear" onClick={() => setFilters(emptyFilters)}>Clear all</button></div>}

    <div className="guest-secondary-tools"><details className="guest-warning-centre"><summary><CircleAlert />Warnings <span>{Object.values(warningCounts).reduce((sum, count) => sum + count, 0)}</span><ChevronDown /></summary><div><button onClick={() => applyQuick("no_table")}><span>Attending without a table</span><strong>{warningCounts.noTable}</strong></button><button onClick={() => setFilters({ ...emptyFilters, advanced: ["meal_missing"] })}><span>Attending without a meal</span><strong>{warningCounts.meal}</strong></button><button onClick={() => setFilters({ ...emptyFilters, advanced: ["missing_email", "missing_phone"] })}><span>Missing contact details</span><strong>{warningCounts.contact}</strong></button><button onClick={() => setFilters({ ...emptyFilters, advanced: ["plus_one_missing"] })}><span>Plus-one without a name</span><strong>{warningCounts.plusOne}</strong></button><span>Transport details missing <strong>{warningCounts.transport}</strong></span><span>Accommodation details missing <strong>{warningCounts.accommodation}</strong></span><span>Potential duplicates <strong>{warningCounts.duplicates}</strong></span></div></details><button onClick={() => setAnalyticsOpen(true)}><BarChart3 />Guest analytics</button><Link href="/guests/households"><UsersRound />Manage households</Link><span>{filtered.length} of {filters.archived ? archivedIds.size : rows.length - archivedIds.size} guests</span></div>
    {saveError && <div className="guest-save-error"><span>{saveError.message}</span><button onClick={() => { const guest = rows.find((item) => item.id === saveError.id); if (guest) updateCell(guest, saveError.field, saveError.value); }}>Retry</button><button onClick={() => setSaveError(null)} aria-label="Dismiss"><X /></button></div>}

    {selected.length > 0 && <BulkBar count={selected.length} pending={isPending} households={households} tables={tables} onAction={performBulk} onExport={() => exportRows(rows.filter((guest) => selected.includes(guest.id)))} onClear={() => setSelected([])} />}
    <section className={`guest-data-surface density-${density}`} aria-busy={isPending}><div className="guest-table-scroll"><table className="guest-workspace-table" aria-label="Wedding guest list"><thead><tr><th><input type="checkbox" checked={allPageSelected} onChange={() => setSelected(allPageSelected ? selected.filter((id) => !paged.some((guest) => guest.id === id)) : [...new Set([...selected, ...paged.map((guest) => guest.id)])])} aria-label="Select guests on this page" /></th><SortHead label="Guest" field="last_name" sort={sort} setSort={setSort} />{columns.household && <SortHead label="Household" field="household" sort={sort} setSort={setSort} />}{columns.type && <SortHead label="Guest type" field="guest_type" sort={sort} setSort={setSort} />}{columns.rsvp && <SortHead label="RSVP" field="rsvp_status" sort={sort} setSort={setSort} />}{columns.meal && <th>Meal</th>}{columns.dietary && <th>Dietary requirements</th>}{columns.table && <SortHead label="Table" field="table" sort={sort} setSort={setSort} />}{columns.invitation && <th>Invitation</th>}{columns.contact && <th>Contact</th>}<th>Actions</th></tr></thead><tbody>{paged.map((guest) => <GuestTableRow key={guest.id} guest={guest} query={debouncedSearch} selected={selected.includes(guest.id)} updated={recentlyUpdated.has(guest.id)} saving={savingId === guest.id} columns={columns} meals={meals} tables={tables} editor={editors[guest.id]} onSelect={() => setSelected((current) => current.includes(guest.id) ? current.filter((id) => id !== guest.id) : [...current, guest.id])} onOpen={() => { setSelectedGuestId(guest.id); setDetailTab("overview"); }} onUpdate={(field, value) => updateCell(guest, field, value)} onDelete={() => removeOne(guest)} />)}</tbody></table>{!paged.length && <div className="guest-workspace-empty"><UsersRound /><h2>No guests match this view</h2><p>Clear a filter or add a new guest to continue.</p><button className="button button-primary" onClick={() => setAddGuestOpen(true)}>Add guest</button></div>}</div><MobileGuestCards guests={paged} selected={selected} query={debouncedSearch} onSelect={(id) => setSelected((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id])} onOpen={setSelectedGuestId} /><footer className="guest-pagination"><span>{filtered.length ? `${(Math.min(page, totalPages) - 1) * pageSize + 1}–${Math.min(Math.min(page, totalPages) * pageSize, filtered.length)} of ${filtered.length}` : "0 results"}</span><label>Rows <select value={pageSize} onChange={(event) => { setPageSize(Number(event.target.value)); setPage(1); }}><option>25</option><option>50</option><option>100</option></select></label><button disabled={page <= 1} onClick={() => setPage((value) => value - 1)} aria-label="Previous page"><ChevronLeft /></button><strong>{Math.min(page, totalPages)} / {totalPages}</strong><button disabled={page >= totalPages} onClick={() => setPage((value) => value + 1)} aria-label="Next page"><ChevronRight /></button></footer></section>

    {addGuestOpen && <AddGuestPanel households={households} tables={tables} meals={meals} initialHouseholdId={initialHouseholdId} onClose={() => setAddGuestOpen(false)} />}
    {householdOpen && <HouseholdPanel onClose={() => setHouseholdOpen(false)} />}
    {importOpen && <ImportPanel onClose={() => setImportOpen(false)} />}
    {reminderOpen && <ReminderPanel guests={reminderGuests} pending={isPending} onClose={() => setReminderOpen(false)} onRecord={(ids) => performBulk("reminder", undefined, ids)} onExport={() => exportRows(reminderGuests, "rsvp-reminders.csv")} />}
    {analyticsOpen && <AnalyticsPanel guests={rows.filter((guest) => !archivedIds.has(guest.id))} meals={meals} tables={tables} onClose={() => setAnalyticsOpen(false)} />}
    {selectedGuestId && <GuestDetailPanel guest={rows.find((item) => item.id === selectedGuestId)} detail={detail} loading={detailLoading} tab={detailTab} editor={editors[selectedGuestId]} updated={recentlyUpdated.has(selectedGuestId)} onTab={setDetailTab} onClose={() => setSelectedGuestId(null)} />}
  </>;
}

function view(id: string, name: string, filters: Filters): SavedView { return { id, name, filters, sort: { field: "last_name", direction: "asc" }, columns: defaultColumns, density: "comfortable" }; }
function isAwaiting(guest: GuestWorkspaceRow) { return ["not_sent", "invited", "awaiting", "maybe"].includes(guest.rsvp_status); }
function matchQuick(guest: GuestWorkspaceRow, filter: string) { if (filter === "all") return true; if (filter === "attending" || filter === "declined") return guest.rsvp_status === filter; if (filter === "awaiting") return isAwaiting(guest); if (filter === "day" || filter === "evening") return guest.guest_type === filter; if (filter === "no_table") return guest.rsvp_status === "attending" && !guest.guest_table_assignments?.length; if (filter === "dietary") return Boolean(guest.dietary_requirements?.trim() || guest.allergies?.trim()); return true; }
function matchAdvanced(guest: GuestWorkspaceRow, filter: string) { if (["adult", "child", "baby"].includes(filter)) return guest.age_group === filter; if (filter === "day") return guest.guest_type === "day"; if (filter === "vip") return guest.is_vip; if (filter === "plus_one") return guest.plus_one_allowed; if (filter === "plus_one_missing") return guest.plus_one_allowed && !guest.plus_one_name; if (filter === "missing_email") return !guest.email; if (filter === "missing_phone") return !guest.phone; if (filter === "accommodation") return guest.requires_accommodation; if (filter === "transport") return guest.requires_transport; if (filter === "accessibility") return Boolean(guest.accessibility_requirements); if (filter === "highchair") return guest.requires_highchair; if (filter === "meal_missing") return guest.rsvp_status === "attending" && !guest.meal_option_id; if (filter === "invitation_not_sent") return guest.invitation_status === "not_sent"; if (filter === "thank_you_not_sent") return !guest.thank_you_sent; return true; }
function compareGuests(a: GuestWorkspaceRow, b: GuestWorkspaceRow, field: string, direction: "asc" | "desc") { const value = (guest: GuestWorkspaceRow) => field === "household" ? guest.households?.household_name || "" : field === "table" ? guest.guest_table_assignments?.[0]?.tables?.name || "" : String(guest[field as keyof GuestWorkspaceRow] || ""); return value(a).localeCompare(value(b), undefined, { numeric: true }) * (direction === "asc" ? 1 : -1); }
function csvCell(value: unknown) { return `"${String(value ?? "").replaceAll('"', '""')}"`; }
function optimisticBulk(guest: GuestWorkspaceRow, action: string, value: string | undefined, households: HouseholdOption[]) { if (action === "rsvp") return { ...guest, rsvp_status: value || guest.rsvp_status }; if (action === "guest_type") return { ...guest, guest_type: value || guest.guest_type }; if (action === "invited") return { ...guest, invitation_status: "sent" }; if (action === "household") { const household = households.find((item) => item.id === value); return { ...guest, household_id: value || null, households: household ? { id: household.id, household_name: household.name, email: household.email, guests: [] } : null }; } if (action === "remove_table") return { ...guest, guest_table_assignments: [] }; return guest; }
function highlight(value: string, query: string) { if (!query) return value; const index = value.toLowerCase().indexOf(query); if (index < 0) return value; return <>{value.slice(0, index)}<mark>{value.slice(index, index + query.length)}</mark>{value.slice(index + query.length)}</>; }

function SortHead({ label, field, sort, setSort }: { label: string; field: string; sort: { field: string; direction: "asc" | "desc" }; setSort: React.Dispatch<React.SetStateAction<{ field: string; direction: "asc" | "desc" }>> }) { return <th><button onClick={() => setSort((current) => ({ field, direction: current.field === field && current.direction === "asc" ? "desc" : "asc" }))}>{label}<span>{sort.field === field ? sort.direction === "asc" ? "↑" : "↓" : ""}</span></button></th>; }

function GuestTableRow({ guest, query, selected, updated, saving, columns, meals, tables, editor, onSelect, onOpen, onUpdate, onDelete }: { guest: GuestWorkspaceRow; query: string; selected: boolean; updated: boolean; saving: boolean; columns: Record<Column, boolean>; meals: Option[]; tables: TableOption[]; editor?: string; onSelect: () => void; onOpen: () => void; onUpdate: (field: string, value: string | null) => void; onDelete: () => void }) {
  const status = statusDisplay(guest.rsvp_status); const StatusIcon = status.icon; const tableId = guest.guest_table_assignments?.[0]?.table_id || "";
  function rowKey(event: React.KeyboardEvent<HTMLTableRowElement>) { if (event.key === "ArrowDown") { event.preventDefault(); (event.currentTarget.nextElementSibling as HTMLElement | null)?.focus(); } if (event.key === "ArrowUp") { event.preventDefault(); (event.currentTarget.previousElementSibling as HTMLElement | null)?.focus(); } if (event.key === "Enter") { event.preventDefault(); onOpen(); } }
  return <tr className={`${updated ? "recently-updated" : ""} ${saving ? "saving" : ""}`} tabIndex={0} onKeyDown={rowKey}><td><input type="checkbox" checked={selected} onChange={onSelect} aria-label={`Select ${guest.first_name}`} /></td><td className="guest-primary-cell"><button onClick={onOpen}><span>{highlight(`${guest.preferred_name || guest.first_name} ${guest.last_name || ""}`.trim(), query)}</span>{guest.preferred_name && guest.preferred_name !== guest.first_name && <small>{guest.first_name} {guest.last_name}</small>}<em>{guest.age_group}{guest.is_vip && <><Star /> VIP</>}</em></button>{editor && <small className="guest-editor-note">{editor} is editing</small>}</td>{columns.household && <td><span>{highlight(guest.households?.household_name || "Ungrouped", query)}</span>{guest.households && <small>{guest.households.guests?.length || 1} people · {guest.households.guests?.filter((item) => item.rsvp_status === "attending").length || 0} attending</small>}</td>}{columns.type && <td><InlineSelect label="Guest type" value={guest.guest_type} onChange={(value) => onUpdate("guest_type", value)} options={[["day", "Day"], ["evening", "Evening"], ["ceremony_only", "Ceremony only"], ["supplier", "Supplier"]]} className={`guest-type-${guest.guest_type}`} /></td>}{columns.rsvp && <td><label className={`guest-status-select status-${guest.rsvp_status}`}><StatusIcon /><select aria-label={`RSVP status for ${guest.first_name}`} value={guest.rsvp_status} onChange={(event) => onUpdate("rsvp_status", event.target.value)}><option value="attending">Attending</option><option value="awaiting">Awaiting</option><option value="declined">Declined</option><option value="maybe">Maybe</option><option value="not_sent">Not invited</option></select></label></td>}{columns.meal && <td><InlineSelect label="Meal" value={guest.meal_option_id || ""} onChange={(value) => onUpdate("meal_option_id", value || null)} options={[["", "No meal"], ...meals.map((meal) => [meal.id, meal.name] as [string, string])]} /></td>}{columns.dietary && <td className="guest-dietary-cell">{guest.allergies ? <strong>Allergy · {highlight(guest.allergies, query)}</strong> : guest.dietary_requirements ? <span>{highlight(guest.dietary_requirements, query)}</span> : <span className="muted">None</span>}</td>}{columns.table && <td><InlineSelect label="Table" value={tableId} onChange={(value) => onUpdate("table_id", value || null)} options={[["", "Unassigned"], ...tables.map((table) => [table.id, table.name] as [string, string])]} /></td>}{columns.invitation && <td><InlineSelect label="Invitation" value={guest.invitation_status} onChange={(value) => onUpdate("invitation_status", value)} options={[["not_sent", "Not sent"], ["sent", "Sent"], ["delivered", "Delivered"], ["returned", "Returned"]]} /></td>}{columns.contact && <td className="guest-contact-cell">{guest.email && <a href={`mailto:${guest.email}`}>{highlight(guest.email, query)}</a>}{guest.phone && <a href={`tel:${guest.phone}`}>{highlight(guest.phone, query)}</a>}{!guest.email && !guest.phone && <span className="muted">Missing</span>}</td>}<td><div className="guest-row-actions"><button onClick={onOpen} aria-label={`Open ${guest.first_name}`}><Pencil /></button><button onClick={onDelete} aria-label={`Delete ${guest.first_name}`}><Trash2 /></button>{saving ? <span>Saving…</span> : updated ? <span>Updated</span> : null}</div></td></tr>;
}

function InlineSelect({ label, value, options, onChange, className = "" }: { label: string; value: string; options: [string, string][]; onChange: (value: string) => void; className?: string }) { return <select className={`guest-inline-select ${className}`} aria-label={label} value={value} onChange={(event) => onChange(event.target.value)}>{options.map(([key, text]) => <option value={key} key={key}>{text}</option>)}</select>; }
function statusDisplay(status: string) { if (status === "attending") return { icon: CheckCircle2, label: "Attending" }; if (status === "declined") return { icon: XCircle, label: "Declined" }; if (status === "maybe") return { icon: HelpCircle, label: "Maybe" }; return { icon: Mail, label: status === "not_sent" ? "Not invited" : "Awaiting" }; }

function MobileGuestCards({ guests, selected, query, onSelect, onOpen }: { guests: GuestWorkspaceRow[]; selected: string[]; query: string; onSelect: (id: string) => void; onOpen: (id: string) => void }) { return <div className="guest-mobile-list">{guests.map((guest) => { const status = statusDisplay(guest.rsvp_status); const StatusIcon = status.icon; return <article key={guest.id}><header><label><input type="checkbox" checked={selected.includes(guest.id)} onChange={() => onSelect(guest.id)} /><strong>{highlight(`${guest.preferred_name || guest.first_name} ${guest.last_name || ""}`, query)}</strong></label><span className={`status-${guest.rsvp_status}`}><StatusIcon />{status.label}</span></header><button onClick={() => onOpen(guest.id)}><p>{guest.households?.household_name || "Ungrouped"}</p><dl><div><dt>Type</dt><dd>{guest.guest_type.replaceAll("_", " ")}</dd></div><div><dt>Meal</dt><dd>{guest.meal_options?.name || "Not selected"}</dd></div><div><dt>Table</dt><dd>{guest.guest_table_assignments?.[0]?.tables?.name || "Unassigned"}</dd></div></dl><span>View guest details</span></button></article>; })}</div>; }

function BulkBar({ count, pending, households, tables, onAction, onExport, onClear }: { count: number; pending: boolean; households: HouseholdOption[]; tables: TableOption[]; onAction: (action: string, value?: string) => void; onExport: () => void; onClear: () => void }) { return <div className="guest-bulk-bar"><strong>{count} selected</strong><button onClick={() => onAction("invited")} disabled={pending}>Mark invitation sent</button><button onClick={() => onAction("reminder")} disabled={pending}>Record reminder</button><select defaultValue="" onChange={(event) => { if (event.target.value) onAction("guest_type", event.target.value); event.target.value = ""; }}><option value="">Change type…</option><option value="day">Day</option><option value="evening">Evening</option><option value="ceremony_only">Ceremony only</option><option value="supplier">Supplier</option></select><select defaultValue="" onChange={(event) => { if (event.target.value) onAction("rsvp", event.target.value); event.target.value = ""; }}><option value="">Change RSVP…</option><option value="attending">Attending</option><option value="awaiting">Awaiting</option><option value="declined">Declined</option><option value="maybe">Maybe</option></select><select defaultValue="" onChange={(event) => { if (event.target.value) onAction("household", event.target.value); event.target.value = ""; }}><option value="">Assign household…</option>{households.map((household) => <option value={household.id} key={household.id}>{household.name}</option>)}</select><select defaultValue="" onChange={(event) => { if (event.target.value) onAction("table", event.target.value); event.target.value = ""; }}><option value="">Assign table…</option>{tables.map((table) => <option value={table.id} key={table.id}>{table.name}</option>)}</select><button onClick={() => onAction("remove_table")}>Remove table</button><button onClick={onExport}>Export</button><button onClick={() => onAction("archive")}>Archive</button><button className="danger" onClick={() => onAction("delete")}>Delete</button><button onClick={onClear}>Clear</button></div>; }

function AddGuestPanel({ households, tables, meals, initialHouseholdId, onClose }: { households: HouseholdOption[]; tables: TableOption[]; meals: Option[]; initialHouseholdId?: string; onClose: () => void }) { return <Panel title="Add guest" note="Start with the essentials, then add any practical details you already know." onClose={onClose}><form action={addGuest} className="guest-panel-form"><div className="form-grid"><Field name="first_name" label="First name" required /><Field name="last_name" label="Last name" required /><Select name="household_id" label="Household" value={initialHouseholdId} options={[["", "No household"], ...households.map((item) => [item.id, item.name] as [string, string])]} /><Select name="guest_type" label="Guest type" options={[["day", "Day guest"], ["evening", "Evening guest"], ["ceremony_only", "Ceremony only"], ["supplier", "Supplier"]]} /><Select name="age_group" label="Age group" options={[["adult", "Adult"], ["child", "Child"], ["baby", "Baby"]]} /><Field name="email" label="Email" type="email" /><Field name="telephone" label="Phone" type="tel" /></div><details><summary>RSVP and food</summary><div className="form-grid"><Select name="rsvp_status" label="RSVP status" options={[["awaiting", "Awaiting"], ["attending", "Attending"], ["declined", "Declined"], ["maybe", "Maybe"]]} /><Select name="invitation_status" label="Invitation" options={[["not_sent", "Not sent"], ["sent", "Sent"], ["delivered", "Delivered"]]} /><Select name="meal_option_id" label="Meal" options={[["", "No meal"], ...meals.map((item) => [item.id, item.name] as [string, string])]} /><Field name="dietary_requirements" label="Dietary requirements" /><Field name="allergies" label="Allergies" /></div></details><details><summary>Travel and seating</summary><div className="form-grid"><Select name="table_id" label="Table" options={[["", "Unassigned"], ...tables.map((item) => [item.id, item.name] as [string, string])]} /><label className="check-label"><input type="checkbox" name="requires_accommodation" />Accommodation required</label><Field name="accommodation_notes" label="Accommodation notes" /><label className="check-label"><input type="checkbox" name="requires_transport" />Transport required</label><Field name="transport_notes" label="Transport notes" /><Field name="accessibility_requirements" label="Accessibility requirements" /><label className="check-label"><input type="checkbox" name="requires_highchair" />Highchair required</label></div></details><details><summary>Plus-one and notes</summary><div className="form-grid"><label className="check-label"><input type="checkbox" name="plus_one_allowed" />Plus-one allowed</label><Field name="plus_one_name" label="Plus-one name" /><label className="check-label"><input type="checkbox" name="is_vip" />VIP guest</label><div className="field span-2"><label>Private notes</label><textarea className="textarea" name="private_notes" /></div></div></details><footer><button className="button button-secondary" name="intent" value="add_another">Save and add another</button><button className="button button-secondary" name="intent" value="open">Save and open guest</button><button className="button button-primary" name="intent" value="save">Save guest</button></footer></form></Panel>; }
function HouseholdPanel({ onClose }: { onClose: () => void }) { return <Panel title="Add household" note="Group people who share an invitation and RSVP code." onClose={onClose}><form action={addHousehold} className="form-grid guest-panel-form"><Field name="name" label="Household name" required /><Field name="primary_email" label="Primary email" type="email" /><Field name="address_line_1" label="Address" /><Field name="city" label="Town or city" /><Field name="postcode" label="Postcode" /><div className="field span-2"><label>Notes</label><textarea className="textarea" name="notes" /></div><footer className="span-2"><Link className="button button-secondary" href="/guests/households">Manage households</Link><button className="button button-primary">Create household</button></footer></form></Panel>; }

function ImportPanel({ onClose }: { onClose: () => void }) { const [fileInfo, setFileInfo] = useState<{ name: string; headers: string[]; preview: string[][]; rows: number; issues: string[] } | null>(null); async function inspect(file?: File) { if (!file) return; const text = await file.text(); const lines = text.split(/\r?\n/).filter(Boolean); const delimiter = (lines[0]?.split("\t").length || 0) > (lines[0]?.split(",").length || 0) ? "\t" : ","; const parsed = lines.map((line) => line.split(delimiter).map((cell) => cell.replace(/^"|"$/g, "").trim())); const headers = parsed[0] || []; const emailIndex = headers.findIndex((header) => /email/i.test(header)); const issues = emailIndex >= 0 ? parsed.slice(1).filter((row) => row[emailIndex] && !/^\S+@\S+\.\S+$/.test(row[emailIndex])).map((_, index) => `Row ${index + 2}: check email address`).slice(0, 5) : []; setFileInfo({ name: file.name, headers, preview: parsed.slice(1, 6), rows: Math.max(0, parsed.length - 1), issues }); }
  return <Panel title="Import guests" note="Upload, review and validate your spreadsheet before confirming the import." onClose={onClose}><form action={importGuests} className="guest-import-wizard"><ol><li className="complete">Upload CSV</li><li className={fileInfo ? "complete" : ""}>Map columns</li><li className={fileInfo ? "complete" : ""}>Preview</li><li className={fileInfo ? "complete" : ""}>Validate</li><li>Confirm</li></ol><label className="guest-import-drop"><Import /><strong>{fileInfo?.name || "Choose a CSV or TSV file"}</strong><span>Excel, Numbers and Google Sheets can export CSV.</span><input type="file" name="csv" accept=".csv,.tsv,text/csv,text/tab-separated-values" required onChange={(event) => void inspect(event.target.files?.[0])} /></label>{fileInfo && <><section><h3>Detected columns</h3><div className="guest-import-columns">{fileInfo.headers.map((header) => <span key={header}>{header}</span>)}</div></section><section><h3>Preview · {fileInfo.rows} rows</h3><div className="guest-import-preview"><table><tbody>{fileInfo.preview.map((row, index) => <tr key={index}>{row.slice(0, 6).map((cell, cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table></div></section>{fileInfo.issues.length > 0 && <div className="alert alert-error"><strong>Review before importing</strong>{fileInfo.issues.map((issue) => <span key={issue}>{issue}</span>)}</div>}<p className="muted small">Existing guests are detected by email or name and skipped. Existing households are matched; missing households are created.</p><button className="button button-primary" disabled={fileInfo.issues.length > 0}>Confirm import</button></>}</form></Panel>; }

function ReminderPanel({ guests, pending, onClose, onRecord, onExport }: { guests: GuestWorkspaceRow[]; pending: boolean; onClose: () => void; onRecord: (ids: string[]) => void; onExport: () => void }) { const [selected, setSelected] = useState(guests.map((guest) => guest.id)); const emails = guests.filter((guest) => selected.includes(guest.id)).map((guest) => guest.email).filter(Boolean).join("; "); const phones = guests.filter((guest) => selected.includes(guest.id)).map((guest) => guest.phone).filter(Boolean).join("\n"); return <Panel title="RSVP reminders" note="Review recipients and prepare your reminder list. Wedding HQ will not send messages without a connected service." onClose={onClose}><div className="guest-reminder-panel"><div className="alert"><Mail /><span>No email or messaging service is connected. Copy or export recipients, then record reminders after contacting them.</span></div><header><strong>{selected.length} recipients</strong><button onClick={() => setSelected(selected.length === guests.length ? [] : guests.map((guest) => guest.id))}>{selected.length === guests.length ? "Clear all" : "Select all"}</button></header><div>{guests.map((guest) => <label key={guest.id}><input type="checkbox" checked={selected.includes(guest.id)} onChange={() => setSelected((current) => current.includes(guest.id) ? current.filter((id) => id !== guest.id) : [...current, guest.id])} /><span><strong>{guest.first_name} {guest.last_name}</strong><small>{guest.email || guest.phone}</small></span></label>)}</div><footer><button className="button button-secondary" onClick={() => void navigator.clipboard.writeText(emails)} disabled={!emails}>Copy emails</button><button className="button button-secondary" onClick={() => void navigator.clipboard.writeText(phones)} disabled={!phones}>Copy phones</button><button className="button button-secondary" onClick={onExport}>Export list</button><button className="button button-primary" onClick={() => onRecord(selected)} disabled={!selected.length || pending}>Record as sent</button></footer></div></Panel>; }

function AnalyticsPanel({ guests, meals, tables, onClose }: { guests: GuestWorkspaceRow[]; meals: Option[]; tables: TableOption[]; onClose: () => void }) { const responded = guests.filter((guest) => ["attending", "declined"].includes(guest.rsvp_status)).length; const assigned = guests.filter((guest) => guest.guest_table_assignments?.length).length; const groups = Array.from(guests.reduce((map, guest) => { const group = guest.relationship_group || "Uncategorised"; map.set(group, (map.get(group) || 0) + 1); return map; }, new Map<string, number>())).sort((a, b) => b[1] - a[1]).slice(0, 8); return <Panel title="Guest analytics" note="A compact planning snapshot. Detailed work stays in the guest list." onClose={onClose}><div className="guest-analytics-grid"><Metric label="RSVP completion" value={`${guests.length ? Math.round(responded / guests.length * 100) : 0}%`} /><Metric label="Seating completion" value={`${guests.length ? Math.round(assigned / guests.length * 100) : 0}%`} /><Metric label="Day / evening" value={`${guests.filter((guest) => guest.guest_type === "day").length} / ${guests.filter((guest) => guest.guest_type === "evening").length}`} /><Metric label="Adults / children" value={`${guests.filter((guest) => guest.age_group === "adult").length} / ${guests.filter((guest) => guest.age_group !== "adult").length}`} /><Metric label="Dietary records" value={guests.filter((guest) => guest.dietary_requirements || guest.allergies).length} /><Metric label="Households" value={new Set(guests.map((guest) => guest.household_id).filter(Boolean)).size} /></div><section className="guest-analytics-list"><h3>Meals</h3>{meals.map((meal) => <div key={meal.id}><span>{meal.name}</span><strong>{guests.filter((guest) => guest.meal_option_id === meal.id).length}</strong></div>)}</section><section className="guest-analytics-list"><h3>Relationship groups</h3>{groups.map(([group, count]) => <div key={group}><span>{group}</span><strong>{count}</strong></div>)}</section><p className="muted small">{tables.length} tables are available for seating.</p></Panel>; }

function GuestDetailPanel({ guest, detail, loading, tab, editor, updated, onTab, onClose }: { guest?: GuestWorkspaceRow; detail: GuestDetailPayload | null; loading: boolean; tab: string; editor?: string; updated: boolean; onTab: (tab: string) => void; onClose: () => void }) { const tabs = ["overview", "rsvp", "food", "seating", "travel", "gifts", "notes", "activity"]; const data = detail?.guest; return <Panel title={guest ? `${guest.preferred_name || guest.first_name} ${guest.last_name || ""}` : "Guest details"} note={guest ? `${guest.households?.household_name || "Ungrouped"} · ${guest.guest_type.replaceAll("_", " ")}` : "Loading guest"} onClose={onClose} wide>{editor && <div className="guest-conflict-banner">{editor} is editing this guest</div>}{updated && <div className="guest-updated-banner">This guest was updated by a collaborator. The latest saved values are shown.</div>}<nav className="guest-detail-tabs">{tabs.map((item) => <button className={tab === item ? "active" : ""} onClick={() => onTab(item)} key={item}>{item}</button>)}</nav>{loading ? <DetailSkeleton /> : data ? <div className="guest-detail-content">{tab === "overview" && <DetailGrid items={[["Full name", `${data.first_name || ""} ${data.last_name || ""}`], ["Preferred name", data.preferred_name], ["Household", (data.households as { household_name?: string } | undefined)?.household_name], ["Guest type", data.guest_type], ["Age group", data.age_group], ["Email", data.email], ["Phone", data.phone], ["VIP", data.is_vip ? "Yes" : "No"], ["Plus-one", data.plus_one_name || (data.plus_one_allowed ? "Allowed — name missing" : "No")]]} />}{tab === "rsvp" && <><DetailGrid items={[["RSVP status", data.rsvp_status], ["Invitation", data.invitation_status], ["Invited", dateValue(data.invited_at)], ["Responded", dateValue(data.responded_at)]]} /><DetailHistory title="Submission history" items={detail.rsvpHistory.map((item) => ({ title: item.attending === true ? "Attending" : item.attending === false ? "Declined" : "Response", detail: item.message_to_couple || item.dietary_requirements || "No message", date: item.submitted_at }))} /></>}{tab === "food" && <><DetailGrid items={[["Meal", (data.meal_options as { name?: string } | undefined)?.name], ["Dietary requirements", data.dietary_requirements], ["Highchair", data.requires_highchair ? "Required" : "No"]]} />{data.allergies && <div className="guest-allergy-warning"><CircleAlert /><div><strong>Allergy</strong><span>{String(data.allergies)}</span></div></div>}</>}{tab === "seating" && <><DetailGrid items={[["Table", guest?.guest_table_assignments?.[0]?.tables?.name || "Unassigned"], ["Seat", data.seat_number]]} /><Link className="button button-secondary" href="/tables">Open seating planner</Link><HouseholdMembers household={data.households} /></>}{tab === "travel" && <DetailGrid items={[["Accommodation", data.requires_accommodation ? "Required" : "Not required"], ["Accommodation notes", data.accommodation_notes], ["Transport", data.requires_transport ? "Required" : "Not required"], ["Transport notes", data.transport_notes], ["Accessibility", data.accessibility_requirements]]} />}{tab === "gifts" && <DetailGrid items={[["Gift received", data.gift_received ? "Yes" : "No"], ["Thank-you required", data.gift_received && !data.thank_you_sent ? "Yes" : "No"], ["Thank-you sent", data.thank_you_sent ? "Yes" : "No"]]} />}{tab === "notes" && <div className="guest-notes-view"><h3>Private notes</h3><p>{String(data.private_notes || "No private notes have been added.")}</p></div>}{tab === "activity" && <DetailHistory title="Guest activity" items={detail.activity.map((item) => ({ title: item.description || item.action.replaceAll("_", " "), detail: item.action.replaceAll("_", " "), date: item.created_at }))} />}<footer className="guest-detail-footer"><Link className="button button-primary" href={`/guests/${guest?.id}`}>Open full guest record</Link></footer></div> : <div className="guest-workspace-empty"><CircleAlert /><p>Guest details could not be loaded.</p></div>}</Panel>; }

function Panel({ title, note, onClose, wide = false, children }: { title: string; note: string; onClose: () => void; wide?: boolean; children: React.ReactNode }) { return <div className="guest-panel-layer" role="dialog" aria-modal="true" aria-label={title}><button className="guest-panel-backdrop" onClick={onClose} aria-label="Close panel" /><aside className={`guest-side-panel ${wide ? "wide" : ""}`}><header><div><p className="eyebrow">Guest management</p><h2>{title}</h2><span>{note}</span></div><button onClick={onClose} aria-label="Close"><X /></button></header>{children}</aside></div>; }
function Field({ name, label, type = "text", required = false }: { name: string; label: string; type?: string; required?: boolean }) { return <div className="field"><label htmlFor={`guest-${name}`}>{label}</label><input className="input" id={`guest-${name}`} name={name} type={type} required={required} /></div>; }
function Select({ name, label, value, options }: { name: string; label: string; value?: string; options: [string, string][] }) { return <div className="field"><label htmlFor={`guest-${name}`}>{label}</label><select className="select" id={`guest-${name}`} name={name} defaultValue={value || ""}>{options.map(([key, text]) => <option value={key} key={key}>{text}</option>)}</select></div>; }
function Metric({ label, value }: { label: string; value: string | number }) { return <div><span>{label}</span><strong>{value}</strong></div>; }
function dateValue(value: unknown) { return value ? new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short", year: "numeric" }).format(new Date(String(value))) : "Not recorded"; }
function DetailGrid({ items }: { items: [string, unknown][] }) { return <dl className="guest-detail-grid">{items.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value === null || value === undefined || value === "" ? "Not recorded" : String(value).replaceAll("_", " ")}</dd></div>)}</dl>; }
function DetailHistory({ title, items }: { title: string; items: Array<{ title: string; detail: string; date: string }> }) { return <section className="guest-detail-history"><h3>{title}</h3>{items.length ? items.map((item, index) => <div key={`${item.date}-${index}`}><i /><div><strong>{item.title}</strong><span>{item.detail}</span><time>{dateValue(item.date)}</time></div></div>) : <p>No history is recorded yet.</p>}</section>; }
function HouseholdMembers({ household }: { household: unknown }) { const members = (household as { guests?: Array<{ id: string; first_name: string; last_name: string; rsvp_status: string }> } | null)?.guests || []; return members.length ? <section className="guest-household-members"><h3>Household members</h3>{members.map((member) => <Link href={`/guests?guest=${member.id}`} key={member.id}><span>{member.first_name} {member.last_name}</span><em>{member.rsvp_status}</em></Link>)}</section> : null; }
function DetailSkeleton() { return <div className="guest-detail-skeleton" aria-label="Loading guest details">{Array.from({ length: 7 }, (_, index) => <i key={index} />)}</div>; }
